-- Read-only, fixed semantic catalogue/guard/global/security observation.
-- No OIDs, role IDs, clock values or cluster paths enter restore comparison.
SELECT jsonb_build_object(
 'schema',current_schema(),
 'sourceOwnership',(SELECT COALESCE(jsonb_agg(jsonb_build_array(c.relname,pg_get_userbyid(c.relowner),c.relacl::text) ORDER BY c.relname COLLATE "C"),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema() AND c.relkind IN ('r','p','v','m','f','S')),
 'sourceFunctionOwnership',(SELECT COALESCE(jsonb_agg(jsonb_build_array(p.proname,pg_get_function_identity_arguments(p.oid),pg_get_userbyid(p.proowner),p.proacl::text) ORDER BY p.proname COLLATE "C",pg_get_function_identity_arguments(p.oid) COLLATE "C"),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=current_schema()),
 'sourceTypeOwnership',(SELECT COALESCE(jsonb_agg(jsonb_build_array(t.typname,pg_get_userbyid(t.typowner),t.typacl::text) ORDER BY t.typname COLLATE "C"),'[]'::jsonb) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname=current_schema()),
 'typeDefinitions',(SELECT COALESCE(jsonb_agg(jsonb_build_array(
   t.typname,t.typtype::text,t.typcategory::text,t.typispreferred,t.typisdefined,t.typlen,t.typbyval,t.typalign::text,t.typstorage::text,t.typdelim::text,t.typnotnull,t.typndims,
   CASE WHEN t.typbasetype<>0 THEN format_type(t.typbasetype,t.typtypmod) ELSE NULL END,
   CASE WHEN t.typelem<>0 THEN format_type(t.typelem,NULL) ELSE NULL END,
   t.typdefault,pg_get_expr(t.typdefaultbin,0),
   (SELECT jsonb_build_array(cn.nspname,c.collname) FROM pg_collation c JOIN pg_namespace cn ON cn.oid=c.collnamespace WHERE c.oid=t.typcollation),
   (SELECT COALESCE(jsonb_agg(e.enumlabel ORDER BY e.enumsortorder),'[]'::jsonb) FROM pg_enum e WHERE e.enumtypid=t.oid),
   (SELECT COALESCE(jsonb_agg(jsonb_build_array(k.conname,k.convalidated,k.condeferrable,k.condeferred,pg_get_constraintdef(k.oid,true)) ORDER BY k.conname COLLATE "C"),'[]'::jsonb) FROM pg_constraint k WHERE k.contypid=t.oid),
   (SELECT COALESCE(jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) ORDER BY a.attnum),'[]'::jsonb) FROM pg_attribute a WHERE a.attrelid=t.typrelid AND a.attnum>0 AND NOT a.attisdropped),
   (SELECT COALESCE(jsonb_agg(jsonb_build_array(x.slot,pn.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) ORDER BY x.slot COLLATE "C"),'[]'::jsonb) FROM (VALUES ('input',t.typinput::oid),('output',t.typoutput::oid),('receive',t.typreceive::oid),('send',t.typsend::oid),('typmodin',t.typmodin::oid),('typmodout',t.typmodout::oid),('analyze',t.typanalyze::oid),('subscript',t.typsubscript::oid)) x(slot,function_id) JOIN pg_proc p ON p.oid=x.function_id JOIN pg_namespace pn ON pn.oid=p.pronamespace),
   (SELECT jsonb_build_array(format_type(r.rngsubtype,NULL),cn.nspname,c.collname,onsp.nspname,op.opcname,pn.nspname,canonical.proname,sn.nspname,diff.proname) FROM pg_range r LEFT JOIN pg_collation c ON c.oid=r.rngcollation LEFT JOIN pg_namespace cn ON cn.oid=c.collnamespace LEFT JOIN pg_opclass op ON op.oid=r.rngsubopc LEFT JOIN pg_namespace onsp ON onsp.oid=op.opcnamespace LEFT JOIN pg_proc canonical ON canonical.oid=r.rngcanonical LEFT JOIN pg_namespace pn ON pn.oid=canonical.pronamespace LEFT JOIN pg_proc diff ON diff.oid=r.rngsubdiff LEFT JOIN pg_namespace sn ON sn.oid=diff.pronamespace WHERE r.rngtypid=t.oid OR r.rngmultitypid=t.oid)
 ) ORDER BY t.typname COLLATE "C"),'[]'::jsonb) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname=current_schema()),
 'relations',(SELECT COALESCE(jsonb_agg(jsonb_build_array(c.relname,c.relkind::text,c.relrowsecurity,c.relforcerowsecurity,c.relispartition) ORDER BY c.relname COLLATE "C"),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema() AND c.relkind IN ('r','p','v','m','f','S')),
 'columns',(SELECT COALESCE(jsonb_agg(jsonb_build_array(c.relname,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid),a.attidentity::text,a.attgenerated::text) ORDER BY c.relname COLLATE "C",a.attnum),'[]'::jsonb) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname=current_schema() AND c.relkind IN ('r','p','v','m','f') AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT COALESCE(jsonb_agg(jsonb_build_array(c.relname,k.conname,k.contype::text,k.convalidated,k.condeferrable,k.condeferred,pg_get_constraintdef(k.oid,true)) ORDER BY c.relname COLLATE "C",k.conname COLLATE "C"),'[]'::jsonb) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema()),
 'indexes',(SELECT COALESCE(jsonb_agg(jsonb_build_array(c.relname,i.indisvalid,i.indisready,i.indimmediate,pg_get_indexdef(i.indexrelid)) ORDER BY c.relname COLLATE "C",pg_get_indexdef(i.indexrelid) COLLATE "C"),'[]'::jsonb) FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema()),
 'functions',(SELECT COALESCE(jsonb_agg(jsonb_build_array(p.proname,pg_get_function_identity_arguments(p.oid),p.prokind::text,p.prosecdef,p.provolatile::text,p.proisstrict,p.proleakproof,p.proparallel::text,p.proconfig,l.lanname,CASE WHEN p.prokind IN ('f','p') THEN pg_get_functiondef(p.oid) ELSE p.prosrc END) ORDER BY p.proname COLLATE "C",pg_get_function_identity_arguments(p.oid) COLLATE "C"),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname=current_schema()),
 'views',(SELECT COALESCE(jsonb_agg(jsonb_build_array(c.relname,pg_get_viewdef(c.oid,true)) ORDER BY c.relname COLLATE "C"),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema() AND c.relkind IN ('v','m')),
 'rules',(SELECT COALESCE(jsonb_agg(jsonb_build_array(c.relname,r.rulename,pg_get_ruledef(r.oid,true)) ORDER BY c.relname COLLATE "C",r.rulename COLLATE "C"),'[]'::jsonb) FROM pg_rewrite r JOIN pg_class c ON c.oid=r.ev_class JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema()),
 'policies',(SELECT COALESCE(jsonb_agg(to_jsonb(p) ORDER BY p.tablename COLLATE "C",p.policyname COLLATE "C"),'[]'::jsonb) FROM pg_policies p WHERE p.schemaname=current_schema()),
 'sequenceDefinitions',(SELECT COALESCE(jsonb_agg(jsonb_build_array(sequencename,data_type,start_value,min_value,max_value,increment_by,cycle,cache_size) ORDER BY sequencename COLLATE "C"),'[]'::jsonb) FROM pg_sequences WHERE schemaname=current_schema()),
 'guards',(SELECT COALESCE(jsonb_agg(jsonb_build_array(c.relname,t.tgname,t.tgenabled::text,pg_get_triggerdef(t.oid,true),p.proname,p.prosrc,p.prosecdef,p.proconfig) ORDER BY c.relname COLLATE "C",t.tgname COLLATE "C"),'[]'::jsonb) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid WHERE n.nspname=current_schema() AND NOT t.tgisinternal),
 'fences',(SELECT COALESCE(jsonb_agg(to_jsonb(f) ORDER BY f."storeId" COLLATE "C"),'[]'::jsonb) FROM "StoreLifecycleFence" f),
 'nonFinalOperations',(SELECT count(*) FROM "StoreLifecycleExecution" WHERE "state" NOT IN ('COMPLETED','REOPENED','ABORTED')),
 'accountSecurityDigest',(SELECT encode(sha256(convert_to(jsonb_build_array((SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a."userId" COLLATE "C"),'[]'::jsonb) FROM "BackofficeStaffAccount" a),(SELECT COALESCE(jsonb_agg(to_jsonb(g) ORDER BY g."userId" COLLATE "C",g."storeId" COLLATE "C"),'[]'::jsonb) FROM "BackofficeStaffGrant" g))::text,'UTF8')),'hex'))
)::text;
